if (field_termination_present) field_termination.PER_encode(ManagementContainer_termination_descr_, p_buf, p_options);
field_eventPosition.PER_encode(ManagementContainer_eventPosition_descr_, p_buf, p_options);
if (field_relevanceDistance_present) field_relevanceDistance.PER_encode(ManagementContainer_relevanceDistance_descr_, p_buf, p_options);
if (field_relevanceTrafficDirection_present) field_relevanceTrafficDirection.PER_encode(ManagementContainer_relevanceTrafficDirection_descr_, p_buf, p_options);
if (field_validityDuration_present) field_validityDuration.PER_encode(ManagementContainer_validityDuration_descr_, p_buf, p_options);
if (field_transmissionInterval_present) field_transmissionInterval.PER_encode(ManagementContainer_transmissionInterval_descr_, p_buf, p_options);
