void ManagementContainer::PER_decode(const TTCN_Typedescriptor_t& p_td, TTCN_Buffer& p_buf, int p_options)
{
clean_up();
boolean ext_bit = p_buf.PER_get_bit();
boolean field_termination_present = p_buf.PER_get_bit();
boolean field_relevanceDistance_present = p_buf.PER_get_bit();
boolean field_relevanceTrafficDirection_present = p_buf.PER_get_bit();
boolean field_validityDuration_present = p_buf.PER_get_bit();
boolean field_transmissionInterval_present = p_buf.PER_get_bit();
field_actionID.PER_decode(ManagementContainer_actionID_descr_, p_buf, p_options);
field_detectionTime.PER_decode(ManagementContainer_detectionTime_descr_, p_buf, p_options);
field_referenceTime.PER_decode(ManagementContainer_referenceTime_descr_, p_buf, p_options);
if (field_termination_present) field_termination.PER_decode(ManagementContainer_termination_descr_, p_buf, p_options);
else field_termination = OMIT_VALUE;
field_eventPosition.PER_decode(ManagementContainer_eventPosition_descr_, p_buf, p_options);
if (field_relevanceDistance_present) field_relevanceDistance.PER_decode(ManagementContainer_relevanceDistance_descr_, p_buf, p_options);
else field_relevanceDistance = OMIT_VALUE;
if (field_relevanceTrafficDirection_present) field_relevanceTrafficDirection.PER_decode(ManagementContainer_relevanceTrafficDirection_descr_, p_buf, p_options);
else field_relevanceTrafficDirection = OMIT_VALUE;
if (field_validityDuration_present) field_validityDuration.PER_decode(ManagementContainer_validityDuration_descr_, p_buf, p_options);
else field_validityDuration = ManagementContainer_validityDuration_defval_;
if (field_transmissionInterval_present) field_transmissionInterval.PER_decode(ManagementContainer_transmissionInterval_descr_, p_buf, p_options);
else field_transmissionInterval = OMIT_VALUE;
field_stationType.PER_decode(ManagementContainer_stationType_descr_, p_buf, p_options);
Vector<boolean> ext_presences;
if (ext_bit) {
INTEGER length_;
int normally_small_length = TRUE;
int mul_16k;
do {
mul_16k = length_.PER_decode_length(p_buf, p_options, normally_small_length);
if (mul_16k > 0) normally_small_length = FALSE;
for (int i = 0; i < length_; ++i) {
ext_presences.push_back(p_buf.PER_get_bit());
}
}
while (mul_16k > 0);
}
int nof_decoded_ext_adds = ext_presences.size();
for (int i = 0; i < nof_decoded_ext_adds; ++i) {
if (ext_presences[i]) PER_skip_opentype(p_buf, p_options);
}
}

