int AlacarteContainer::OER_encode(const TTCN_Typedescriptor_t&, TTCN_Buffer& p_buf) const
{
  if (!is_bound()) {
  TTCN_EncDec_ErrorContext::error(TTCN_EncDec::ET_UNBOUND,
    "Encoding an unbound record value.");
  return -1;
  }
  char c = 0;
  if (field_lanePosition.is_present()) {
    c |= 64;
  }
  if (field_impactReduction.is_present()) {
    c |= 32;
  }
  if (field_externalTemperature.is_present()) {
    c |= 16;
  }
  if (field_roadWorks.is_present()) {
    c |= 8;
  }
  if (field_positioningSolution.is_present()) {
    c |= 4;
  }
  if (field_stationaryVehicle.is_present()) {
    c |= 2;
  }
  p_buf.put_c(c);
  if (field_lanePosition.is_present())
    field_lanePosition.OER_encode(AlacarteContainer_lanePosition_descr_, p_buf);
  if (field_impactReduction.is_present())
    field_impactReduction.OER_encode(AlacarteContainer_impactReduction_descr_, p_buf);
  if (field_externalTemperature.is_present())
    field_externalTemperature.OER_encode(AlacarteContainer_externalTemperature_descr_, p_buf);
  if (field_roadWorks.is_present())
    field_roadWorks.OER_encode(AlacarteContainer_roadWorks_descr_, p_buf);
  if (field_positioningSolution.is_present())
    field_positioningSolution.OER_encode(AlacarteContainer_positioningSolution_descr_, p_buf);
  if (field_stationaryVehicle.is_present())
    field_stationaryVehicle.OER_encode(AlacarteContainer_stationaryVehicle_descr_, p_buf);
  return 0;
}

int AlacarteContainer::OER_decode(const TTCN_Typedescriptor_t&, TTCN_Buffer& p_buf, OER_struct& p_oer)
{
  const unsigned char* uc = p_buf.get_read_data();
  p_buf.increase_pos(1);
  boolean has_extension = FALSE;
  if (uc[0] & 0x80) {
    has_extension = TRUE;
  }
  if (uc[0] & 64)
    field_lanePosition.OER_decode(AlacarteContainer_lanePosition_descr_, p_buf, p_oer);
 else
    field_lanePosition = OMIT_VALUE;
  if (uc[0] & 32)
    field_impactReduction.OER_decode(AlacarteContainer_impactReduction_descr_, p_buf, p_oer);
 else
    field_impactReduction = OMIT_VALUE;
  if (uc[0] & 16)
    field_externalTemperature.OER_decode(AlacarteContainer_externalTemperature_descr_, p_buf, p_oer);
 else
    field_externalTemperature = OMIT_VALUE;
  if (uc[0] & 8)
    field_roadWorks.OER_decode(AlacarteContainer_roadWorks_descr_, p_buf, p_oer);
 else
    field_roadWorks = OMIT_VALUE;
  if (uc[0] & 4)
    field_positioningSolution.OER_decode(AlacarteContainer_positioningSolution_descr_, p_buf, p_oer);
 else
    field_positioningSolution = OMIT_VALUE;
  if (uc[0] & 2)
    field_stationaryVehicle.OER_decode(AlacarteContainer_stationaryVehicle_descr_, p_buf, p_oer);
 else
    field_stationaryVehicle = OMIT_VALUE;
  if (has_extension) {
    size_t bytes = decode_oer_length(p_buf, FALSE);
    uc = p_buf.get_read_data();
    p_buf.increase_pos(bytes);
    uc++;
  }
  return 0;
}

void AlacarteContainer::PER_encode(const TTCN_Typedescriptor_t& p_td, TTCN_Buffer& p_buf, int p_options) const
{
if (!is_bound()) {
TTCN_EncDec_ErrorContext::error(TTCN_EncDec::ET_UNBOUND, "Encoding an unbound SEQUENCE value.");
return;
}
boolean ext_bit = FALSE;
p_buf.PER_put_bit(ext_bit);
boolean field_lanePosition_present = field_lanePosition.is_present();
p_buf.PER_put_bit(field_lanePosition_present);
boolean field_impactReduction_present = field_impactReduction.is_present();
p_buf.PER_put_bit(field_impactReduction_present);
boolean field_externalTemperature_present = field_externalTemperature.is_present();
p_buf.PER_put_bit(field_externalTemperature_present);
boolean field_roadWorks_present = field_roadWorks.is_present();
p_buf.PER_put_bit(field_roadWorks_present);
boolean field_positioningSolution_present = field_positioningSolution.is_present();
p_buf.PER_put_bit(field_positioningSolution_present);
boolean field_stationaryVehicle_present = field_stationaryVehicle.is_present();
p_buf.PER_put_bit(field_stationaryVehicle_present);
if (field_lanePosition_present) field_lanePosition.PER_encode(AlacarteContainer_lanePosition_descr_, p_buf, p_options);
if (field_impactReduction_present) field_impactReduction.PER_encode(AlacarteContainer_impactReduction_descr_, p_buf, p_options);
if (field_externalTemperature_present) field_externalTemperature.PER_encode(AlacarteContainer_externalTemperature_descr_, p_buf, p_options);
if (field_roadWorks_present) field_roadWorks.PER_encode(AlacarteContainer_roadWorks_descr_, p_buf, p_options);
if (field_positioningSolution_present) field_positioningSolution.PER_encode(AlacarteContainer_positioningSolution_descr_, p_buf, p_options);
if (field_stationaryVehicle_present) field_stationaryVehicle.PER_encode(AlacarteContainer_stationaryVehicle_descr_, p_buf, p_options);
}

void AlacarteContainer::PER_decode(const TTCN_Typedescriptor_t& p_td, TTCN_Buffer& p_buf, int p_options)
{
clean_up();
boolean ext_bit = p_buf.PER_get_bit();
boolean field_lanePosition_present = p_buf.PER_get_bit();
boolean field_impactReduction_present = p_buf.PER_get_bit();
boolean field_externalTemperature_present = p_buf.PER_get_bit();
boolean field_roadWorks_present = p_buf.PER_get_bit();
boolean field_positioningSolution_present = p_buf.PER_get_bit();
boolean field_stationaryVehicle_present = p_buf.PER_get_bit();
if (field_lanePosition_present) field_lanePosition.PER_decode(AlacarteContainer_lanePosition_descr_, p_buf, p_options);
else field_lanePosition = OMIT_VALUE;
if (field_impactReduction_present) field_impactReduction.PER_decode(AlacarteContainer_impactReduction_descr_, p_buf, p_options);
else field_impactReduction = OMIT_VALUE;
if (field_externalTemperature_present) field_externalTemperature.PER_decode(AlacarteContainer_externalTemperature_descr_, p_buf, p_options);
else field_externalTemperature = OMIT_VALUE;
if (field_roadWorks_present) field_roadWorks.PER_decode(AlacarteContainer_roadWorks_descr_, p_buf, p_options);
else field_roadWorks = OMIT_VALUE;
if (field_positioningSolution_present) field_positioningSolution.PER_decode(AlacarteContainer_positioningSolution_descr_, p_buf, p_options);
else field_positioningSolution = OMIT_VALUE;
if (field_stationaryVehicle_present) field_stationaryVehicle.PER_decode(AlacarteContainer_stationaryVehicle_descr_, p_buf, p_options);
else field_stationaryVehicle = OMIT_VALUE;
Vector<boolean> ext_presences;
if (ext_bit) {
INTEGER length_;
int normally_small_length = TRUE;
int mul_16k;
do {
mul_16k = length_.PER_decode_length(p_buf, p_options, normally_small_length);
if (mul_16k > 0) normally_small_length = FALSE;
for (int i = 0; i < length_; ++i) {
ext_presences.push_back(p_buf.PER_get_bit());
}
}
while (mul_16k > 0);
}
int nof_decoded_ext_adds = ext_presences.size();
for (int i = 0; i < nof_decoded_ext_adds; ++i) {
if (ext_presences[i]) PER_skip_opentype(p_buf, p_options);
}
}

