int StationaryVehicleContainer::OER_encode(const TTCN_Typedescriptor_t&, TTCN_Buffer& p_buf) const
{
  if (!is_bound()) {
  TTCN_EncDec_ErrorContext::error(TTCN_EncDec::ET_UNBOUND,
    "Encoding an unbound record value.");
  return -1;
  }
  char c = 0;
  if (field_stationarySince.is_present()) {
    c |= 128;
  }
  if (field_stationaryCause.is_present()) {
    c |= 64;
  }
  if (field_carryingDangerousGoods.is_present()) {
    c |= 32;
  }
  if (field_numberOfOccupants.is_present()) {
    c |= 16;
  }
  if (field_vehicleIdentification.is_present()) {
    c |= 8;
  }
  if (field_energyStorageType.is_present()) {
    c |= 4;
  }
  p_buf.put_c(c);
  if (field_stationarySince.is_present())
    field_stationarySince.OER_encode(StationaryVehicleContainer_stationarySince_descr_, p_buf);
  if (field_stationaryCause.is_present())
    field_stationaryCause.OER_encode(StationaryVehicleContainer_stationaryCause_descr_, p_buf);
  if (field_carryingDangerousGoods.is_present())
    field_carryingDangerousGoods.OER_encode(StationaryVehicleContainer_carryingDangerousGoods_descr_, p_buf);
  if (field_numberOfOccupants.is_present())
    field_numberOfOccupants.OER_encode(StationaryVehicleContainer_numberOfOccupants_descr_, p_buf);
  if (field_vehicleIdentification.is_present())
    field_vehicleIdentification.OER_encode(StationaryVehicleContainer_vehicleIdentification_descr_, p_buf);
  if (field_energyStorageType.is_present())
    field_energyStorageType.OER_encode(StationaryVehicleContainer_energyStorageType_descr_, p_buf);
  return 0;
}

