void DENM_header_encoder(const ITS__Container::ItsPduHeader& input_value, OCTETSTRING& output_stream, TTCN_EncDec::coding_t coding_type, unsigned int extra_options)
{
TTCN_Buffer ttcn_buf;
input_value.encode(DENM_header_descr_, ttcn_buf, coding_type, extra_options);
ttcn_buf.get_string(output_stream);
}

INTEGER DENM_header_decoder(OCTETSTRING& input_stream, ITS__Container::ItsPduHeader& output_value, TTCN_EncDec::coding_t coding_type, unsigned int extra_options)
{
TTCN_EncDec::clear_error();
TTCN_Buffer ttcn_buf(input_stream);
output_value.decode(DENM_header_descr_, ttcn_buf, coding_type, extra_options);
switch (TTCN_EncDec::get_last_error_type()) {
case TTCN_EncDec::ET_NONE:
ttcn_buf.cut();
ttcn_buf.get_string(input_stream);
return 0;
case TTCN_EncDec::ET_INCOMPL_MSG:
case TTCN_EncDec::ET_LEN_ERR:
return 2;
default:
return 1;
}
}

